 c.require(set(m['fixture_sha256'])=={'empty.php','true.php'},'Fixture inventory drift')
 for name,pin in m['fixture_sha256'].items():c.require(c.sha((EVIDENCE/name).read_bytes())==pin,'Local fixture bytes drift')
